-- Badge catalog v2 (2026-09-05): 40 tiered achievements + 3 one-time specials.
-- Forward-only: preserve earned rows, timestamps and XP snapshots. Reward changes
-- apply only to future awards. Preserve an admin's existing activation choice.
on conflict (code) do update set
  name = excluded.name, description = excluded.description,
  icon = excluded.icon, icon_url = excluded.icon_url,
  xp = excluded.xp, xp_reward = excluded.xp_reward, criteria = excluded.criteria;
